CREATE DATABASE IF NOT EXISTS quetta_skills CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE quetta_skills;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS inquiries, courses, freelancers, academies, course_categories, freelancer_categories, admins;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE admins (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE academies (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,location VARCHAR(150),image VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE course_categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE freelancer_categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE courses (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,academy_id INT NOT NULL,category_id INT NOT NULL,description TEXT,fee DECIMAL(10,2) DEFAULT 0,duration VARCHAR(80),location VARCHAR(150),image VARCHAR(255),featured TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(academy_id) REFERENCES academies(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES course_categories(id) ON DELETE RESTRICT);
CREATE TABLE freelancers (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,category_id INT NOT NULL,bio TEXT,experience VARCHAR(80),location VARCHAR(150),image VARCHAR(255),featured TINYINT(1) DEFAULT 0,status ENUM('active','hidden') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES freelancer_categories(id) ON DELETE RESTRICT);
CREATE TABLE inquiries (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40),message TEXT NOT NULL,inquiry_type VARCHAR(40) DEFAULT 'general',status ENUM('new','read','resolved') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
